exercises.reference_solution:
def check_sign(n):
    if n > 0:
        return 'positive'
    elif n < 0:
        return 'negative'
    else:
        return 'zero'

def fizz_buzz_single(n):
    if n % 15 == 0:
        return 'FizzBuzz'
    elif n % 3 == 0:
        return 'Fizz'
    elif n % 5 == 0:
        return 'Buzz'
    else:
        return str(n)

def sum_to_n(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

def count_positives(numbers):
    count = 0
    for x in numbers:
        if x > 0:
            count += 1
    return count

def find_maximum(numbers):
    best = numbers[0]
    for x in numbers[1:]:
        if x > best:
            best = x
    return best

def find_minimum(numbers):
    best = numbers[0]
    for x in numbers[1:]:
        if x < best:
            best = x
    return best

def filter_evens(numbers):
    evens = []
    for x in numbers:
        if x % 2 == 0:
            evens.append(x)
    return evens

def word_frequencies(words):
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return counts

def sum_list(elements):
    total = 0
    for x in elements:
        total += x
    return total

def find_index(elements, target):
    for i, x in enumerate(elements):
        if x == target:
            return i
    return -1

def count_occurrences(elements, target):
    count = 0
    for x in elements:
        if x == target:
            count += 1
    return count

def is_palindrome_str(s):
    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1
    return True

def build_counts(items):
    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1
    return counts

def has_duplicate(elements):
    seen = set()
    for x in elements:
        if x in seen:
            return True
        seen.add(x)
    return False
